<?php
require_once __DIR__.'/includes/layout.php';require_permission('attendance.view');$schoolId=tenant_id();$pdo=db();$date=valid_date($_GET['date']??'')??date('Y-m-d');$classId=(int)($_GET['class_id']??0);$flash=take_flash();
$c=$pdo->prepare('SELECT id,name FROM classes WHERE school_id=:school_id ORDER BY name');$c->execute(['school_id'=>$schoolId]);$classes=$c->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_permission('attendance.create');$student=(int)($_POST['student_id']??0);$status=$_POST['status']??'';if(!$student||!in_array($status,['present','absent','late'],true)){flash('error','Select a student and a valid attendance status.');redirect('attendance.php');}$q=$pdo->prepare('SELECT id FROM students WHERE id=:id AND school_id=:school_id AND deleted_at IS NULL');$q->execute(['id'=>$student,'school_id'=>$schoolId]);if(!$q->fetchColumn()){flash('error','Student is outside the current school.');redirect('attendance.php');}$q=$pdo->prepare('INSERT INTO attendance(uuid,school_id,student_id,attendance_date,status,notes,client_uuid) VALUES(:uuid,:school_id,:student,:date,:status,:notes,:client) ON DUPLICATE KEY UPDATE status=VALUES(status),notes=VALUES(notes)');$uuid=bin2hex(random_bytes(16));$q->execute(['uuid'=>$uuid,'school_id'=>$schoolId,'student'=>$student,'date'=>valid_date($_POST['attendance_date']??'')??date('Y-m-d'),'status'=>$status,'notes'=>clamp_text($_POST['notes']??'',MAX_TEXT_LENGTH)?:null,'client'=>$uuid]);audit('create','attendance',(string)$student);flash('success','Attendance saved.');redirect('attendance.php?date='.u(valid_date($_POST['attendance_date']??'')??date('Y-m-d')).'&class_id='.(int)($_POST['class_id']??0));}
$students=[];if($classId){$q=$pdo->prepare('SELECT id,admission_no,first_name,last_name FROM students WHERE school_id=:school_id AND class_id=:class_id AND deleted_at IS NULL ORDER BY first_name,last_name');$q->execute(['school_id'=>$schoolId,'class_id'=>$classId]);$students=$q->fetchAll();}$q=$pdo->prepare('SELECT a.attendance_date,a.status,a.notes,s.admission_no,s.first_name,s.last_name,c.name class_name FROM attendance a JOIN students s ON s.id=a.student_id AND s.school_id=a.school_id LEFT JOIN classes c ON c.id=s.class_id AND c.school_id=s.school_id WHERE a.school_id=:school_id AND a.attendance_date=:date ORDER BY c.name,s.first_name');$q->execute(['school_id'=>$schoolId,'date'=>$date]);$rows=$q->fetchAll();admin_header('Attendance');?><div class="content"><?php if($flash):?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif;?><div class="panel"><div class="panel-head"><h2>Daily attendance</h2></div><form method="get" class="actions"><input type="date" name="date" value="<?=e($date)?>"><select name="class_id"><option value="">Select class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId==(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn secondary">Load</button></form><?php if($classId):?><form method="post" class="grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><input type="hidden" name="class_id" value="<?=$classId?>"><div class="field"><label>Student</label><select name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['admission_no'].' · '.$s['first_name'].' '.$s['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Status</label><select name="status"><option>present</option><option>absent</option><option>late</option></select></div><div class="field full"><label>Notes</label><input name="notes"></div><div class="actions"><button class="btn">Save attendance</button></div></form><?php else:?><p class="empty">Select a class to load its students.</p><?php endif;?></div><div class="panel"><div class="panel-head"><h2>Attendance for <?=e($date)?></h2></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['admission_no'].' · '.$r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['status'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach;if(!$rows):?><tr><td class="empty" colspan="4">No attendance recorded for this date.</td></tr><?php endif;?></tbody></table></div></div></div><?php admin_footer();
